import { AccountType, AccountStatus } from "../../../infrastructure/database/models/accounts.model";

export { AccountType, AccountStatus };

/**
 * Account domain model returned to API clients.
 *
 * - `id`        internal UUID primary key.
 * - `accountId` human-friendly identifier (ACC000001), unique per user,
 *               generated by the service — never supplied by the client.
 * - `userId`    owner, always derived from the authenticated JWT context.
 * - `currentBalance` kept as a string because it maps to a Postgres
 *               DECIMAL(15,2); it is not freely editable through this module
 *               (the future transaction module owns balance changes).
 */
export interface Account {
  id: string;
  accountId: string;
  accountName: string;
  bank: string;
  accountNumber: string | null;
  customerNumber: string | null;
  ifsc: string | null;
  type: AccountType;
  status: AccountStatus;
  currentBalance: string;
  openingDate: string | null;
  closingDate: string | null;
  userId: string;
  createdAt: Date;
  updatedAt: Date;
}
